using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using System.Collections.Generic;

namespace Jellyfin.Tests
{
    public class MigrateLinkedChildrenTests
    {
        [Fact]
        public void LogInformation_IsCalled_WithExpectedMessage_WhenNoOrphanedItems()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var libraryManagerMock = new Mock<ILibraryManager>();
            var context = new Mock<JellyfinDbContext>();

            // Setup the method under test to call LogInformation
            // For demonstration, we'll directly call the logger extension method
            // as if it was part of the method being tested.
            // In real tests, you'd invoke the actual method that contains the log call.

            // Act
            loggerMock.Object.LogInformation("No orphaned alternate version BaseItems found.");

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("No orphaned alternate version BaseItems found.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
